import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { getAssociatedFranchises, fetchDurationOptions, createUserExamData } from '../services/api';

const AssociatedFranchises = () => {
  const navigate = useNavigate();
  const [examData, setExamData] = useState({
    examName: [],
    date: new Date().toISOString().split('T')[0],
    durationInMinutes: [],
    status: 'Inprogress',
    franchiseId: [],
  });
  const [franchiseList, setFranchiseList] = useState([]);
  const [durationList, setDurationList] = useState([]);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);
  const [userFullName, setUserFullName] = useState('');

  const validExamNames = [
    'ServiceNow: CAD', 'ServiceNow: CSA', 'ServiceNow: Platform Developer',
    'ServiceNow: HR AND IMPLEMENTATION', 'ServiceNow: CLOUD ARCHITECTURE',
    'Salesforce developer', 'Salesforce administrators', 'Google cloud', 
    'Mulesoft', 'Fusion', 'PSI'
  ];

  const validStatuses = ['completed', 'Absent', 'Inprogress'];

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const [franchiseData, durationData] = await Promise.all([
          getAssociatedFranchises(),
          fetchDurationOptions(),
        ]);

        setFranchiseList(franchiseData || []);
        setDurationList(durationData.options || []);
      } catch (error) {
        setError(error.message || 'Failed to fetch data.');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleCheckboxChange = (e, field) => {
    const { value, checked } = e.target;
    setExamData((prevData) => ({
      ...prevData,
      [field]: checked
        ? [...prevData[field], value]
        : prevData[field].filter((item) => item !== value),
    }));
  };

  const handleUserFullNameChange = (e) => {
    const value = e.target.value;
    setUserFullName(value);
    setExamData((prevData) => ({
      ...prevData,
      name: value,
    }));
  };

  const validateForm = () => {
    if (!userFullName.trim()) return 'Please provide the full name.';
    if (examData.examName.length === 0) return 'Please select at least one exam name.';
    if (examData.durationInMinutes.length === 0) return 'Please select at least one exam duration.';
    if (examData.franchiseId.length === 0) return 'Please select at least one franchise.';
    return null;
  };

  const handleCreateExamData = async (e) => {
    e.preventDefault();

    const validationError = validateForm();
    if (validationError) {
      setError(validationError);
      return;
    }

    setLoading(true);
    try {
      const payload = examData.examName.map((exam) => ({
        name: userFullName,
        examName: exam,
        date: new Date(examData.date).toISOString().split('T')[0],
        durationInMinutes: examData.durationInMinutes.map((d) => parseInt(d, 10)),
        status: examData.status.trim(),
        franchiseId: examData.franchiseId,
      }));

      await Promise.all(
        payload.map((data) => createUserExamData([data], examData.franchiseId))
      );

      setSuccess('Exam data created successfully!');
      navigate(-1);
      setExamData({
        examName: [],
        date: new Date().toISOString().split('T')[0],
        durationInMinutes: [],
        status: 'Inprogress',
        franchiseId: [],
      });
      setUserFullName('');
      setError(null);
    } catch (error) {
      setError(error.response?.data?.message || error.message || 'Failed to create exam data.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={styles.container}>
      <h2 style={styles.header}>Associated Franchise</h2>

      {loading && <p style={styles.loading}>Loading...</p>}
      {error && <p style={styles.error}>{error}</p>}
      {success && <p style={styles.success}>{success}</p>}

      <h3 style={styles.formTitle}>Create Exam Data</h3>
      <form onSubmit={handleCreateExamData} style={styles.form}>
        <div style={styles.formGroup}>
          <label htmlFor="userFullName" style={styles.label}>Full Name</label>
          <input
            type="text"
            name="userFullName"
            value={userFullName}
            onChange={handleUserFullNameChange}
            required
            style={styles.input}
          />
        </div>

        <div style={styles.formGroup}>
          <label htmlFor="examName" style={styles.label}>Exam Name</label>
          {validExamNames.map((exam, index) => (
            <div key={index}>
              <input
                type="checkbox"
                value={exam}
                checked={examData.examName.includes(exam)}
                onChange={(e) => handleCheckboxChange(e, 'examName')}
              />
              <span>{exam}</span>
            </div>
          ))}
        </div>

        <div style={styles.formGroup}>
          <label htmlFor="date" style={styles.label}>Exam Date</label>
          <input
            type="date"
            name="date"
            value={examData.date}
            onChange={(e) => setExamData({ ...examData, date: e.target.value })}
            required
            style={styles.input}
          />
        </div>

        <div style={styles.formGroup}>
          <label htmlFor="durationInMinutes" style={styles.label}>Duration (Minutes)</label>
          {durationList.map((duration, index) => (
            <div key={index}>
              <input
                type="checkbox"
                value={duration}
                checked={examData.durationInMinutes.includes(duration)}
                onChange={(e) => handleCheckboxChange(e, 'durationInMinutes')}
              />
              <span>{duration} minutes</span>
            </div>
          ))}
        </div>

        <div style={styles.formGroup}>
          <label htmlFor="franchiseId" style={styles.label}>Select Franchise</label>
          {franchiseList.map((franchise) => (
            <div key={franchise._id}>
              <input
                type="checkbox"
                value={franchise._id}
                checked={examData.franchiseId.includes(franchise._id)}
                onChange={(e) => handleCheckboxChange(e, 'franchiseId')}
              />
              <span>{franchise.name}</span>
            </div>
          ))}
        </div>

        <button type="submit" disabled={loading} style={styles.submitButton}>
          {loading ? 'Submitting...' : 'Create Exam Data'}
        </button>
      </form>
    </div>
  );
};

const styles = {
  container: { maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'Arial, sans-serif' },
  header: { textAlign: 'center', fontSize: '2rem', marginBottom: '20px' },
  formTitle: { textAlign: 'center', fontSize: '1.5rem', marginBottom: '20px' },
  form: { display: 'flex', flexDirection: 'column', gap: '15px' },
  formGroup: { display: 'flex', flexDirection: 'column' },
  label: { fontWeight: 'bold', marginBottom: '5px' },
  input: { padding: '10px', marginBottom: '10px' },
  submitButton: { padding: '10px', backgroundColor: '#4CAF50', color: '#fff', borderRadius: '5px' },
  loading: { textAlign: 'center', color: '#666' },
  error: { color: 'red', textAlign: 'center' },
  success: { color: 'green', textAlign: 'center' },
};

export default AssociatedFranchises;
